 1	import { readFileSync } from "node:fs";
 2	
 3	function deny(reason: string): never {
 4		throw new Error(reason);
 5	}
 6	
 7	// The hook is a guard for literal CLI invocations, not a shell sandbox. Never
 8	// evaluate shell text or accept authorization from assistant/tool messages.
 9	function check(raw: string): void {
10		const input = JSON.parse(raw);
11		const command: unknown = input?.tool_input?.command;
12		if (typeof command !== "string") deny("missing Bash command in hook input");
13		const invocations = [
14			...command
15				.replace(/\\\r?\n/g, "")
16				.matchAll(
17					/(?:\bmob|\$MOB|\$\{MOB\})["']?\s+["']?sign["']?(?=\s|$)([^\n;&|]*)/g,
18				),
19		];
20		if (!invocations.length) return;
21		const ids = invocations.map((match) => {
22			const tokens = match[1]
23				.trim()
24				.split(/\s+/)
25				.map((s) => s.replace(/^(?:"([^"]*)"|'([^']*)')$/, "$1$2"));
26			const ids: string[] = [];
27			for (let i = 0; i < tokens.length; i++) {
28				const token = tokens[i];
29				if (token.startsWith("#")) break;
30				if (token === "--") continue;
31				if (token === "--with") {
32					if (!["browser", "keystore"].includes(tokens[++i]))
33						deny("use a literal signer backend");
34					continue;
35				}
36				if (/^--with=(browser|keystore)$/.test(token)) continue;
37				if (!/^p-[1-9]\d*$/.test(token))
38					deny("use one literal Proposal id in each sign command");
39				ids.push(token);
40			}
41			if (ids.length !== 1)
42				deny("use one literal Proposal id in each sign command");
43			return ids[0];
44		});
45		if (typeof input.transcript_path !== "string" || !input.transcript_path)
46			deny("no transcript_path; cannot verify the latest user message");
47		const transcript = readFileSync(input.transcript_path, "utf8");
48		let latest: unknown;
49		for (const line of transcript.split("\n")) {
50			if (!line.trim()) continue;
51			const event = JSON.parse(line);
52			if (event.type === "user") {
53				if (event.message?.role !== "user")
54					deny("invalid latest user message in transcript");
55				latest = event.message.content;
56			}
57		}
58		const message =
59			typeof latest === "string"
60				? latest
61				: Array.isArray(latest)
62					? latest
63							.filter(
64								(part) => part?.type === "text" && typeof part.text === "string",
65							)
66							.map((part) => part.text)
67							.join("\n")
68					: "";
69		for (const id of ids)
70			if (!new RegExp(`(?<![A-Za-z0-9_-])${id}(?![A-Za-z0-9_-])`).test(message))
71				deny(`the latest user message must name the exact Proposal id ${id}`);
72	}
73	
74	export function signGuard(raw: string, err: (text: string) => void): number {
75		try {
76			check(raw);
77			return 0;
78		} catch (error) {
79			err(
80				`mob sign blocked: ${error instanceof Error ? error.message : String(error)}`,
81			);
82			return 2;
83		}
84	}
